package com.amrshalaby.timesheet.timesheet;
import io.micronaut.http.annotation.*; import io.micronaut.security.annotation.Secured; import io.micronaut.security.rules.SecurityRule; import io.micronaut.views.View; import java.time.YearMonth; import java.util.*;
@Controller("/timesheets") @Secured(SecurityRule.IS_AUTHENTICATED) public class TimesheetController { private final MonthGridService grids; public TimesheetController(MonthGridService grids){this.grids=grids;} @Get @View("timesheet") public Map<String,Object> current(){YearMonth now=YearMonth.now(); return view(now.getYear(),now.getMonthValue());} @Get("/{year}/{month}") @View("timesheet") public Map<String,Object> view(int year,int month){var grid=grids.build(year,month); return Map.of("title","Timesheet","grid",grid,"status",TimesheetStatus.DRAFT,"entries",Map.of(),"monthlyTotal","00:00");} }
